-- GEMA Seed-Import «recherche1» (2026-07-14) — aus Chat-Recherche via --import
-- ALLE Records status='nicht_verifiziert'. Neue Records: ON CONFLICT DO NOTHING (idempotent).
-- AUSFÜHREN: Supabase Dashboard → SQL Editor → einfügen → Run.
-- Rollback (alle Seed-Records): supabase/gema_lieferanten_seed_rollback.sql

on conflict (module_key, data_key) do nothing;

-- ERSETZT bestehende Basis-Seed-Records (reichere Datenblatt-Version, gleiche ID
-- → kein Duplikat im Katalog). Überschreibt bewusst: DO UPDATE.
on conflict (module_key, data_key) do update set payload = excluded.payload;
